const LIGHTHOUSE_ART_ALIGNED = new WeakSet();
function mePos() {
  const c = S.hero; if (!c) return { x: 50, y: 50 };
  if (c.zone === 'westfall' && c.at === 'lighthouse' && !LIGHTHOUSE_ART_ALIGNED.has(c)) {
    c.pos = { x: PLACES.lighthouse.x, y: PLACES.lighthouse.y };
    LIGHTHOUSE_ART_ALIGNED.add(c);
  }
